"""Jinja2 source templates for the Mantle system prompt.

The prompt text lives in the flat ``.jinja2`` files next to this module —
one file per prompt section, no subfolders.  They are read once at import
time into the constants below; rendering and whitespace normalization happen
in :mod:`rasa.mantle.prompts.renderer`.
"""

from importlib.resources import files

_TEMPLATE_DIR = files("rasa.mantle.prompts.templates")


def _read_template(file_name: str) -> str:
    return _TEMPLATE_DIR.joinpath(file_name).read_text(encoding="utf-8")


AGENT_HEADER_TEMPLATE = _read_template("agent_header.jinja2")
CURRENT_DATETIME_TEMPLATE = _read_template("current_datetime.jinja2")
CHANNEL_RULES_TEMPLATE = _read_template("channel_rules.jinja2")
ACKNOWLEDGEMENT_TEMPLATE = _read_template("acknowledgement.jinja2")
LIFECYCLE_TOOLS_TEMPLATE = _read_template("lifecycle_tools.jinja2")
ACTIVE_SKILL_TEMPLATE = _read_template("active_skill.jinja2")
KNOWLEDGE_ANSWERING_TEMPLATE = _read_template("knowledge_answering.jinja2")
PROJECT_TEMPLATE = _read_template("project.jinja2")
PENDING_TOOL_CONFIRMATION_TEMPLATE = _read_template("pending_tool_confirmation.jinja2")
ROUTING_CATALOG_TEMPLATE = _read_template("routing_catalog.jinja2")
SCOPE_HANDLING_TEMPLATE = _read_template("scope_handling.jinja2")
REPHRASE_TASK_TEMPLATE = _read_template("rephrase_task.jinja2")
ACK_REMINDER_TEMPLATE = _read_template("ack_reminder.jinja2")
CANNED_UTTER_NOTICE_TEMPLATE = _read_template("canned_utter_notice.jinja2")
SKIPPED_COLLECT_NOTICE_TEMPLATE = _read_template("skipped_collect_notice.jinja2")
REPHRASE_INSTRUCTION_TEMPLATE = _read_template("rephrase_instruction.jinja2")
CONFIRM_REPHRASE_INSTRUCTION_TEMPLATE = _read_template(
    "confirm_rephrase_instruction.jinja2"
)
SET_FIELDS_FILL_TASK_TEMPLATE = _read_template("set_fields_fill_task.jinja2")
SET_FIELDS_FILL_INSTRUCTION_TEMPLATE = _read_template(
    "set_fields_fill_instruction.jinja2"
)
